import{_ as e,o as l,c as d,ag as i}from"./chunks/framework.CmaAMB6e.js";const x=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"learning-by-agent","text":"技能模块化学习系统","tagline":"前端工程师的跨技能学习系统 · 每个技能独立成线，前端知识作锚","actions":[{"theme":"brand","text":"选择技能开始","link":"/android/"},{"theme":"alt","text":"添加新技能","link":"/#添加新技能"}]},"features":[{"title":"Android (Kotlin)","details":"Jetpack Compose 声明式 UI。28 个概念，从 Hello World 到架构、性能、安全。","link":"/android/","linkText":"进入 Android →"},{"title":"iOS (Swift)","details":"SwiftUI 声明式 UI。28 个概念，覆盖语法、UI、工程化与资深实战。","link":"/ios/","linkText":"进入 iOS →"},{"title":"鸿蒙 (ArkTS)","details":"ArkUI 声明式 UI。28 个概念，含分布式能力与组件化。","link":"/harmony/","linkText":"进入 鸿蒙 →"},{"title":"Python","details":"数据处理、Web 后端与 AI 应用。29 个概念，pandas、FastAPI、LLM 到部署。","link":"/python/","linkText":"进入 Python →"},{"title":"Java","details":"后端开发与 Spring Boot。29 个概念，从语言核心到 JVM、微服务与部署。","link":"/java/","linkText":"进入 Java →"},{"title":"前端","details":"完整前端学习线。29 个概念，从浏览器原理到 React/Vue、架构与性能治理。","link":"/frontend/","linkText":"进入 前端 →"},{"title":"Node.js","details":"运行时原理与后端开发。29 个概念，从事件循环到 NestJS、微服务与部署。","link":"/nodejs/","linkText":"进入 Node.js →"},{"title":"数据库","details":"后端基石。29 个概念，从 SQL 到索引、NoSQL 与分布式数据库。","link":"/database/","linkText":"进入 数据库 →"},{"title":"Linux","details":"服务器运维。29 个概念，从命令到 systemd、Docker 与故障排查。","link":"/linux/","linkText":"进入 Linux →"},{"title":"系统设计","details":"架构师思维。27 个概念，从容量估算到高可用与经典案例。","link":"/system-design/","linkText":"进入 系统设计 →"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1784195062000}'),a={name:"index.md"};function o(n,t,r,s,c,k){return l(),d("div",null,[...t[0]||(t[0]=[i('<h2 id="系统理念" tabindex="-1">系统理念 <a class="header-anchor" href="#系统理念" aria-label="Permalink to &quot;系统理念&quot;">​</a></h2><p>本系统<strong>不再把多种语言杂糅在一篇文档里对比</strong>，而是把每个技能拆成独立的学习线：</p><ul><li>每个技能有自己的<strong>学习路径、环境搭建、概念教程、笔记、进度</strong></li><li>技能之间互不干扰，可以单独推进任何一个</li><li>每篇概念教程聚焦单一技能，自成闭环</li><li>末尾保留轻量「前端对照」小节，用你已会的 React/Vue/JS 帮助理解新概念</li></ul><h2 id="如何开始" tabindex="-1">如何开始 <a class="header-anchor" href="#如何开始" aria-label="Permalink to &quot;如何开始&quot;">​</a></h2><ol><li>选择一个技能（上方卡片），进入它的模块</li><li>先读该技能的「环境搭建」，搭好开发环境</li><li>按「学习路径」的概念序列，从 <code>01</code> 顺序学习</li><li>边学边在「学习笔记」沉淀速查与踩坑</li><li>每完成一个概念，在「学习进度」更新状态</li><li>卡住时用 Skill 陪练：<code>/explain &lt;技能&gt; &lt;概念&gt;</code>、<code>/quiz &lt;技能&gt; &lt;概念&gt;</code></li></ol><h2 id="添加新技能" tabindex="-1">添加新技能 <a class="header-anchor" href="#添加新技能" aria-label="Permalink to &quot;添加新技能&quot;">​</a></h2><p>复制 <code>templates/skill-template/</code> 目录到 <code>skills/&lt;新技能名&gt;/</code>，按其中的模板填写即可。然后在 <code>.vitepress/config.mjs</code> 的 <code>sidebar</code> 和 <code>nav</code> 中加入新技能入口。</p><h2 id="陪练-skill" tabindex="-1">陪练 Skill <a class="header-anchor" href="#陪练-skill" aria-label="Permalink to &quot;陪练 Skill&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td><code>/explain &lt;技能&gt; &lt;概念&gt;</code></td><td>以前端视角解释陌生概念</td><td><code>/explain android 协程</code></td></tr><tr><td><code>/practice &lt;技能&gt; &lt;概念&gt;</code></td><td>生成针对性练习任务</td><td><code>/practice ios 状态管理</code></td></tr><tr><td><code>/quiz &lt;技能&gt; &lt;概念&gt;</code></td><td>自测出题并判分</td><td><code>/quiz python 异步编程</code></td></tr><tr><td><code>/track &lt;技能&gt; &lt;动作&gt;</code></td><td>更新该技能进度</td><td><code>/track android 完成 02</code></td></tr><tr><td><code>/assess &lt;技能&gt; &lt;等级&gt;</code></td><td>AI 考核是否达到某等级</td><td><code>/assess android 3</code></td></tr></tbody></table>',9)])])}const p=e(a,[["render",o]]);export{x as __pageData,p as default};
